    private static void click(View view,String label){if(view instanceof Button&&((Button)view).getText().toString().equals(label)){view.performClick();return;}if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)click(group.getChildAt(i),label);}}
    private static EditText findInput(View view){if(view instanceof EditText)return (EditText)view;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++){EditText found=findInput(group.getChildAt(i));if(found!=null)return found;}}return null;}
    private final class AudioServer implements AutoCloseable {
        private final ServerSocket socket=new ServerSocket(0);final Set<String> requests=ConcurrentHashMap.newKeySet();
        AudioServer()throws Exception{Thread worker=new Thread(()->{while(!socket.isClosed())try{Socket client=socket.accept();Thread request=new Thread(()->respond(client));request.setDaemon(true);request.start();}catch(Exception ignored){}});worker.setDaemon(true);worker.start();}
        String base(){return "http://127.0.0.1:"+socket.getLocalPort();}
        private void respond(Socket client){try(Socket connection=client){connection.setSoTimeout(5000);BufferedReader input=new BufferedReader(new InputStreamReader(connection.getInputStream(),"US-ASCII"));String first=input.readLine(),line;String path=first.split(" ")[1].split("\\?")[0];long start=0;while((line=input.readLine())!=null&&!line.isEmpty())if(line.toLowerCase(Locale.ROOT).startsWith("range: bytes=")){String range=line.substring(line.indexOf('=')+1).split("-")[0];if(!range.isEmpty())start=Long.parseLong(range);}requests.add(path);byte[] body;String mime;if(path.endsWith(".wav")){body=BackgroundPlaybackChecks.wav(path.equals("/a.wav")||path.equals("/b.wav")?1300:20000);mime="audio/wav";}else{try(InputStream stream=test.getContext().getAssets().open("port-fixtures"+path)){ByteArrayOutputStream output=new ByteArrayOutputStream();byte[] buffer=new byte[8192];int count;while((count=stream.read(buffer))!=-1)output.write(buffer,0,count);body=output.toByteArray();}mime=path.endsWith(".m3u8")?"application/vnd.apple.mpegurl":"video/mp2t";}int offset=(int)Math.min(start,body.length);String headers="HTTP/1.1 "+(start>0?"206 Partial Content":"200 OK")+"\r\nContent-Type: "+mime+"\r\nContent-Length: "+(body.length-offset)+"\r\nAccept-Ranges: bytes\r\n"+(start>0?"Content-Range: bytes "+offset+"-"+(body.length-1)+"/"+body.length+"\r\n":"")+"Connection: close\r\n\r\n";connection.getOutputStream().write(headers.getBytes("US-ASCII"));connection.getOutputStream().write(body,offset,body.length-offset);}catch(Exception ignored){}}
        public void close()throws Exception{socket.close();}
    }
